// KNN-7x20 Direction Vote 3D Signal Analysis Model
// KNN vote margin + neighbour disagreement, crisp vs contested 3D blocks

kIn = input(7, "K Neighbors", 1, 20, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
librarySize = input(200, "Library Size", 30, 500, 10)
marginThresh = input(0.43, "Margin Threshold", 0.05, 1.0, 0.01)
disagreeThresh = input(0.50, "Disagreement Threshold", 0.05, 2.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Raw feature f = (close - close[1]) / close[1] ─────────
denom = close[1] + 0.000000001
f = (close - close[1]) / denom

// ─── Persistent feature & close history for variable indexing ─
varip fHist = array(0)
varip cHist = array(0)
array.push(fHist, f)
array.push(cHist, close)
n = array.size(fHist)

// ─── KNN search over library ────────────────────────────────
upVotes = 0
downVotes = 0
meanD = 0.0
stdevD = 0.0
voteMargin = 0.0
disagree = 0.0

warmup = n >= featureBars + librarySize + 1

if warmup {
    bestDist = array()
    bestTarget = array()
    ii = 0
    while ii < kIn {
        array.push(bestDist, 999999.0)
        array.push(bestTarget, 0)
        ii := ii + 1
    }

    curEnd = n - 1
    maxLag = librarySize
    if n - featureBars - 1 < maxLag { maxLag := n - featureBars - 1 }

    lag = 1
    while lag <= maxLag {
        pEnd = curEnd - lag
        // Distance D(lag) = sqrt(sum((V(t)[j]-V(p)[j])^2))
        ssd = 0.0
        j = 0
        while j < featureBars {
            a = fHist[curEnd - j]
            b = fHist[pEnd - j]
            d = a - b
            ssd := ssd + d * d
            j := j + 1
        }
        dist = sqrt(ssd)
        // Label L(p) = +1 if close[p+1] > close[p] else -1
        lab = 0 - 1
        if cHist[pEnd + 1] > cHist[pEnd] { lab := 1 }
        // Insert into k smallest
        insertIdx = 0 - 1
        m = 0
        while m < kIn {
            if dist < bestDist[m] {
                insertIdx := m
                m := kIn
            }
            m := m + 1
        }
        if insertIdx >= 0 {
            m = kIn - 1
            while m > insertIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestTarget, m, bestTarget[m - 1])
                m := m - 1
            }
            array.set(bestDist, insertIdx, dist)
            array.set(bestTarget, insertIdx, lab)
        }
        lag := lag + 1
    }

    // Count votes among k neighbours
    up = 0
    dn = 0
    m = 0
    while m < kIn {
        if bestDist[m] < 999999.0 {
            if bestTarget[m] == 1 { up := up + 1 }
            else { dn := dn + 1 }
        }
        m := m + 1
    }
    upVotes := up
    downVotes := dn

    // Channel 1: Vote Margin M = (up - down) / k
    voteMargin := (up - dn) / kIn

    // Channel 2: Disagreement S = stdev(D) / mean(D)
    sumD = 0.0
    m = 0
    while m < kIn {
        sumD := sumD + bestDist[m]
        m := m + 1
    }
    mu = sumD / kIn
    meanD := mu
    varD = 0.0
    m = 0
    while m < kIn {
        dd = bestDist[m] - mu
        varD := varD + dd * dd
        m := m + 1
    }
    varD := varD / kIn
    sd = sqrt(varD)
    stdevD := sd
    disagree := sd / (mu + 0.000000001)
}

// ─── Signal conditions: both channels must agree ────────────
buySig = warmup and voteMargin > marginThresh and disagree < disagreeThresh
sellSig = warmup and voteMargin < 0 - marginThresh and disagree < disagreeThresh

// ─── Cone size from crispness (proportional to signal quality) ─
crisp = abs(voteMargin) - marginThresh + (disagreeThresh - disagree)
rawSize = 0.6 + crisp * 1.5
coneSize = rawSize * markerSize
if coneSize < 0.6 { coneSize := 0.6 }
if coneSize > 2.2 { coneSize := 2.2 }

// ─── 2D signal markers on main chart ────────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 3D cones in the SAME pane as geometry ──────────────────
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", coneSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", coneSize, 0, "separate")
}

// ─── Unconditional rendering LAST ───────────────────────────
// Channel 1 twin: vote margin line
plot(voteMargin, "Vote Margin M", "#b48cff", 2)
plot(marginThresh, "Margin +Thresh", "rgba(180,140,255,0.5)", 1)
plot(0 - marginThresh, "Margin -Thresh", "rgba(180,140,255,0.5)", 1)
// Channel 2 twin: disagreement line in its own scale
plot(disagree, "Disagreement S", "#ffd43b", 1, "separate2")
plot(disagreeThresh, "Disagree Thresh", "rgba(255,212,59,0.5)", 1, "separate2")
// 3D form: M as bar height (tall pillar = crisp, flat slab = contested)
plot3d(voteMargin * 100, "Vote Margin Blocks", "bars3d", "#b48cff", "separate")
// 3D form: S as independent second channel at distinct depth
plot3d(disagree * 100, "Disagreement Depth", "ribbon", "#ffd43b", "separate", 1)

// Visible Session Value Terrain
// Volume-profile-on-chart: POC + value area from visible session, leaving-value signals.

rows = input(24, "Rows Per Session", 6, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
lookSessions = input(3, "Lookback Sessions", 1, 10, 1)
terrMult = input(1.0, "Terrain Height Multiplier", 0.2, 3.0, 0.1)
show3d = input(true, "Show 3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session window from lookback ────────────────────────────────
sessLen = lookSessions * 50
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
sessRng = sessHigh - sessLow
sessRngFix = sessRng
if sessRngFix <= 0 {
    sessRngFix := close * 0.01
}

// ─── Volume-at-price bins over session window ────────────────────
binVol = array()
b = 0
while b < rows {
    array.push(binVol, 0.0)
    b := b + 1
}
totalVol = 0.0
j = 0
while j < sessLen {
    tp = (high[j] + low[j] + close[j]) / 3
    vv = volume[j]
    bi = floor((tp - sessLow) / sessRngFix * rows)
    if bi < 0 {
        bi := 0
    }
    if bi > rows - 1 {
        bi := rows - 1
    }
    array.set(binVol, bi, array.get(binVol, bi) + vv)
    totalVol := totalVol + vv
    j := j + 1
}
if totalVol <= 0 {
    totalVol := 1.0
}

// ─── Point of control ────────────────────────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
k = 1
while k < rows {
    v = array.get(binVol, k)
    if v > pocVal {
        pocVal := v
        pocBin := k
    }
    k := k + 1
}
pocPrice = sessLow + (pocBin + 0.5) / rows * sessRngFix
pocNorm = pocVal / totalVol

// ─── Value area expand-from-POC ──────────────────────────────────
vaLowBin = pocBin
vaHighBin = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLowBin > 0 {
        leftVal := array.get(binVol, vaLowBin - 1)
    }
    rightVal = 0 - 1.0
    if vaHighBin < rows - 1 {
        rightVal := array.get(binVol, vaHighBin + 1)
    }
    if rightVal >= leftVal and vaHighBin < rows - 1 {
        vaHighBin := vaHighBin + 1
        accum := accum + rightVal
    } else {
        if vaLowBin > 0 {
            vaLowBin := vaLowBin - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHighBin + 1) / rows * sessRngFix
valPrice = sessLow + vaLowBin / rows * sessRngFix

// ─── Terrain height from current-price bin ───────────────────────
curBin = floor((close - sessLow) / sessRngFix * rows)
if curBin < 0 {
    curBin := 0
}
if curBin > rows - 1 {
    curBin := rows - 1
}
curVol = array.get(binVol, curBin)
curNorm = 0.0
if pocVal > 0 {
    curNorm := curVol / pocVal
}
terrainLevel = sessLow + curNorm * sessRngFix * terrMult

// ─── Signals: price leaving value ────────────────────────────────
vahPrev = vahPrice[1]
valPrev = valPrice[1]
buySig = close[1] <= vahPrev and close > vahPrice
sellSig = close[1] >= valPrev and close < valPrice

// ─── Cone size from leave strength ───────────────────────────────
leaveDist = 0.0
if buySig {
    leaveDist := close - vahPrice
}
if sellSig {
    leaveDist := valPrice - close
}
coneSize = 1.0 + abs(leaveDist) / sessRngFix * 20
if coneSize < 0.6 {
    coneSize := 0.6
}
if coneSize > 2.2 {
    coneSize := 2.2
}
coneSize := coneSize * markerSize

var wasPocBin = -1

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig and show3d {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", coneSize, 1, "3d")
}
if sellSig and show3d {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", coneSize, 1, "3d")
}
if pocBin != wasPocBin and show3d {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}
wasPocBin := pocBin

// ─── 2D twins: same POC / value info when 3D is off ──────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "Value Area High", "#22cc88", 1, "stepline")
plot(valPrice, "Value Area Low", "#ff4477", 1, "stepline")
fill(vahPrice, valPrice, "rgba(34,204,136,0.12)")

// ─── 3D: value terrain + POC rail + value edges ──────────────────
plot3d(terrainLevel, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "Value High Edge", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain lvl = highest(high, 20) recomputed every bar.
// FIX 2: close[-1] reads a future bar — changed to close > lvl for a present-bar breakout.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine syntax — changed to plotshape(bar_index, low, "Buy", "triangleup", "#22cc88").
// FIX 4: plot3d(r, "RSI", "surface", "#b48cff", "3d") forces an oscillator into the price scene — changed pane to "separate".
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot3d(r, "RSI", "surface", "#b48cff", "separate")
